-- AlterTable
ALTER TABLE "Category" ADD COLUMN     "serviceTags" TEXT[] DEFAULT ARRAY[]::TEXT[],
ADD COLUMN     "staged" BOOLEAN NOT NULL DEFAULT false;

-- M9-B data. Moves the live taxonomy to the client's 24 category Master Directory, in place, so listings stay attached
-- and every category keeps its web address. Every statement is a no-op on an empty database (a fresh install gets the
-- same data from prisma/seed.ts) and on a second run. The old categories are matched by slug, the sub-categories by
-- name. Four old categories were folded into others (Taxi & Private Hire and Car Services, Legal & Financial and
-- Business Consultants, Trades & Contractors and Electrician / Plumber, Health & Care and Fitness & Wellbeing), their
-- listings move to the surviving category and the folded one is deleted when nothing points at it any more.

-- 1. Park the old sub-categories we know about (matched by their old slug) under a prefix, so the new ones can reuse their names.
UPDATE "Subcategory" SET name = '~old~' || name, slug = '~old~' || slug WHERE "categoryId" = (SELECT id FROM "Category" WHERE slug = 'restaurants-and-takeaways') AND slug IN ('restaurants-and-takeaways-bangladeshi-restaurants', 'restaurants-and-takeaways-curry-houses', 'restaurants-and-takeaways-bengali-indian-takeaways');
